-- SELECT-only; all rows and both accepted flags must be present/true. Not activation approval.
SELECT 'payment-closing' AS package,'public.record_transaction_payment(uuid,numeric,text,uuid,uuid)' AS signature,md5(p.prosrc) AS actual_md5, md5(p.prosrc) IN ('e39b532635f0aa14a30992c6a87b3de9','e9e88c3e70c76450ecc89744adc78471') AS accepted_body,r.rolname='postgres' AND p.prosecdef AND p.proconfig=ARRAY['search_path=public']::text[] AND p.proacl::text='{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' AS accepted_security FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.record_transaction_payment(uuid,numeric,text,uuid,uuid)'::regprocedure;
SELECT 'payment-closing' AS package,'public.close_finance_cash_session(uuid,jsonb,text)' AS signature,md5(p.prosrc) AS actual_md5, md5(p.prosrc) IN ('2e6b21c915118dbf490796b0ecd86868','e994975f0e77a0c692ba3d89e5772538') AS accepted_body,r.rolname='postgres' AND p.prosecdef AND p.proconfig=ARRAY['search_path=public']::text[] AND p.proacl::text='{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' AS accepted_security FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.close_finance_cash_session(uuid,jsonb,text)'::regprocedure;
SELECT 'refund' AS package,'public.create_finance_refund(uuid,uuid,numeric,text,text,uuid,text)' AS signature,md5(p.prosrc) AS actual_md5, md5(p.prosrc) IN ('695152a80fcd4e561759f34b27652c5a','80bcdeabfc038907ee6dcea4d9d0e714') AS accepted_body,r.rolname='postgres' AND p.prosecdef AND p.proconfig=ARRAY['search_path=public']::text[] AND p.proacl::text='{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' AS accepted_security FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.create_finance_refund(uuid,uuid,numeric,text,text,uuid,text)'::regprocedure;
